mapper.select:
SELECT rno, bno, reply, replyer, replydate, updatedate
FROM (
    SELECT ROW_NUMBER() OVER (ORDER BY rno ASC) rn, rno, bno, reply, replyer, replydate, updatedate
    FROM tbl_reply WHERE bno = #{bno} AND rno > 0
)
WHERE rn > (CAST(#{cri.pageNum} AS DECIMAL(19,0)) - 1) * #{cri.amount}
  AND rn <= CAST(#{cri.pageNum} AS DECIMAL(19,0)) * #{cri.amount}
ORDER BY rn
